typedef unsigned int nlUint32;
typedef int nlInt32;
typedef unsigned long nlUint64;
typedef nlUint32 nslSourceId;
typedef nlUint32 nslSoundId;
typedef nlUint32 nslEmitterId;
typedef float nlMatrix4x4[4][4] __attribute__((aligned(16)));
typedef float nlVector3d[3];

#define NSL_NUM_SOURCES 512
#define NSL_NUM_SOUNDS 256
#define NSL_NUM_EMITTERS 256
#define NSL_NUM_SOUNDS_PER_EMITTERS 16
#define FILENAME_LENGTH 48

enum nslSourceTypeEnum {
    NSL_SOURCETYPE_SFX,
    NSL_SOURCETYPE_AMBIENT,
    NSL_SOURCETYPE_MUSIC,
    NSL_SOURCETYPE_VOICE,
    NSL_SOURCETYPE_MOVIE,
    NSL_SOURCETYPE_USER1,
    NSL_SOURCETYPE_USER2
};

enum _nslClearBehaviour {
    NSL_CLEAR_INIT,
    NSL_CLEAR_RESET,
    NSL_CLEAR_FREE
};

enum nslSpeakerModeEnum {
    NSL_SPEAKER_STEREO,
    NSL_SPEAKER_MONO,
    NSL_SPEAKER_HEADPHONE,
    NSL_SPEAKER_PROLOGIC,
    NSL_SPEAKER_DOLBY_51,
    NSL_SPEAKER_Z
};

enum nslOutputModeEnum {
    NSL_OUTPUT_ANALOG,
    NSL_OUTPUT_DIGITAL,
    NSL_OUTPUT_BOTH,
    NSL_OUTPUT_Z
};

enum nslLanguageEnum {
    NSL_LANGUAGE_ZERO
};

enum nslPs2CdDvdMode {
    NSL_PS2_CD_MODE,
    NSL_PS2_DVD_MODE
};

template<class T>
class fifo_queue {
private:
    T *queue;
    short queue_max;
    short start;
    short end;
    short count;

public:
    void init(short size);
    void clear();
    void free();
};

struct nslSource {
    bool used;
    bool looping;
    char fileName[FILENAME_LENGTH];
    int bank;
    nslSourceId myId;
    float length;
    float paddedLength;
    nslSourceTypeEnum type;
    nlUint32 gasSourceId;
    float rawVolume;
    float pitch;
    float minDist;
    float maxDist;
};

struct nslSound {
    bool isReady;
    bool used;
    bool inRange;
    bool isReallyReady;
    bool isPlaying;
    bool isReallyPlaying;
    bool looping;
    bool isQueuing;
    short left;
    short right;
    short old_left;
    short old_right;
    nlUint32 gasInstanceId;
    nlInt32 pauseCount;
    nlInt32 dampenCount;
    nslSourceId myId;
    nslSourceId mySource;
    nslEmitterId myEmitter;
    float rawVolume;
    float positionalVolume;
    float angle;
    float pitch;
    float minDist;
    float maxDist;
};

struct nslEmitter {
    bool used;
    bool autoRelease;
    bool isALineEmitter;
    nslEmitterId myId;
    nlVector3d startPosition;
    nlVector3d endPosition;
    nlVector3d position;
    fifo_queue<nslSoundId> emittedSounds;
};

struct nslSystem {
    nslSystem() : firstInit(1), initialized(0), on(false) {}

    nlMatrix4x4 listenerPo;
    nslSource sourceSlots[NSL_NUM_SOURCES];
    nslSound soundSlots[NSL_NUM_SOUNDS];
    nslEmitter emitterSlots[NSL_NUM_EMITTERS];
    nlUint32 sourceSlotsUsedCount;
    nlUint32 soundSlotsUsedCount;
    nlUint32 emitterSlotsUsedCount;
    nlInt32 firstInit;
    nlInt32 initialized;
    nlUint32 numBanks;
    fifo_queue<nslSoundId> queuedSounds;
    nslSpeakerModeEnum speakerMode;
    nslOutputModeEnum outputMode;
    nslLanguageEnum language;
    nslPs2CdDvdMode cdDvdMode;
    nlUint64 lastClock;
    bool on;
    bool proview;
    bool finalizeSourcesEnabled;
};

extern nslSystem nsl;
extern const char nsl_illegal_slot[];
void nslFatal(const char *format, ...);

__asm__(".equ nsl, 0x0048B5F0");
__asm__(".equ nsl_illegal_slot, 0x0050C6A0");
__asm__(".equ nslFatal__FPCce, 0x00391420");
__asm__(".equ init__t10fifo_queue1ZUis, 0x00391628");
__asm__(".equ clear__t10fifo_queue1ZUi, 0x003915E0");
__asm__(".equ free__t10fifo_queue1ZUi, 0x00391670");

void _nslClearEmitterSlot( nlUint32 whichSlot, bool resetId, _nslClearBehaviour
                           clearStyle )
{
  if ( whichSlot >= NSL_NUM_EMITTERS )
    nslFatal(nsl_illegal_slot);
  nslEmitter *mySlot = &nsl.emitterSlots[whichSlot];

  if (resetId)
    mySlot->myId = whichSlot;

  mySlot->used = false;
  mySlot->autoRelease = false;
  mySlot->isALineEmitter = false;

  mySlot->startPosition[0] = 0.0f;
  mySlot->startPosition[1] = 0.0f;
  mySlot->startPosition[2] = 0.0f;

  mySlot->endPosition[0] = 0.0f;
  mySlot->endPosition[1] = 0.0f;
  mySlot->endPosition[2] = 0.0f;

  mySlot->position[0] = 0.0f;
  mySlot->position[1] = 0.0f;
  mySlot->position[2] = 0.0f;
  switch (clearStyle)
  {
    case NSL_CLEAR_INIT:  mySlot->emittedSounds.init(NSL_NUM_SOUNDS_PER_EMITTERS); break;
    case NSL_CLEAR_RESET: mySlot->emittedSounds.clear();                break;
    case NSL_CLEAR_FREE:  mySlot->emittedSounds.free();                 break;
  }
}
